REFERENCE = [750,35,30,30,44.5,3,246,50,77,.9,30,10,10,5,28,10,25,37,2,5,18,17,.47,1.9,.055,.065]

def evaluate(params):
    if len(params) != 26:
        raise ValueError("Expected 26 inputs")
    for i,(x,lo,hi) in enumerate(zip(params,MININPUT,MAXINPUT)):
        if not lo <= x <= hi:
            raise ValueError(f"Input {i}={x} outside published normalization range [{lo},{hi}]")
    x = [2*(v-lo)/(hi-lo)-1 for v,lo,hi in zip(params,MININPUT,MAXINPUT)]
    hidden = [math.tanh(VALW[j*28+2]+sum(x[i]*VALW[j*28+3+i] for i in range(26))) for j in range(9)]
    y = VALW[0]+sum(hidden[j]*VALW[j*28+1] for j in range(9))
    return MINOUPUT[0]+.5*(MAXOUPUT[0]-MINOUPUT[0])*(y+1)

if __name__ == "__main__":
    assert len(VALW)==253
    raw=evaluate(REFERENCE)
    corrected=raw*(1-.0142)-3*.00087342
    print(json.dumps({"network":"B.7 Rn_9_0 (example)","reference_raw":raw,"reference_corrected":corrected,"printed_module_raw":1.13509,"raw_difference":raw-1.13509,"printed_module_corrected":1.11635116861,"weight_count":len(VALW)},indent=2))
    for i,value in [(9,.7),(9,.8),(4,35),(4,55)]:
        point=REFERENCE.copy();point[i]=value
        print(json.dumps({"changed_input_index":i,"value":value,"TBR":evaluate(point)}))
    try:
        outside=REFERENCE.copy();outside[4]=80;evaluate(outside)
    except ValueError as exc:
        print("Expected domain rejection:",exc)
    else:
        raise AssertionError("Extrapolation was not rejected")
